/// <summary>
/// Task 269070: CB887 - BlueYonder to D365 (Intercompany Replenishment) - Build (D365) - (SG) Part 6
/// Update the product receipt number based on the referenced SO packing slip number.
/// </summary>
/// <param name = "_num">Receipt number</param>
/// <param name = "_purchTable">PurchTable</param>
/// <param name = "_overrideNum">Override line number</param>
/// <returns></returns>
protected Num getParmTableNum(Num _num, PurchTable _purchTable, Num _overrideNum)
{
    next getParmTableNum(_num, _purchTable, _overrideNum);

    if (_purchTable.METIntercompanyTransferReplenishment)
    {
        _num = PurchLine::getProductReceiptForReplenishmentOrder(_purchTable.PurchId);
    }

    return _num;
}
